package kr.devfive.hanbeon

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.Service
import android.content.Intent
import android.graphics.PixelFormat
import android.os.Build
import android.os.IBinder
import android.provider.Settings
import android.view.Gravity
import android.view.WindowManager

/**
 * 4칸 컨트롤러를 다른 앱 위에 올린다.
 *
 * 이 제품은 '다른 앱을 조작하는 것'이라 우리 화면이 앞에 나오면 안 된다. 그래서
 * Activity가 아니라 포그라운드 Service가 `TYPE_APPLICATION_OVERLAY` 창을 직접 올린다.
 * Tauri의 안드로이드 지원은 Activity만 주기 때문에 여기는 순수 안드로이드로 짠다.
 *
 * 포그라운드 서비스로 두는 이유는 오래 살아야 하기 때문이다. 사용자는 스위치 말고
 * 다른 조작 수단이 없어서, 시스템이 우리를 조용히 죽이면 되살릴 방법이 없다.
 */
class OverlayService : Service() {
    private var windows: WindowManager? = null
    private var controller: ControllerView? = null
    private var usb: UsbSwitch? = null
    private var highlight: HighlightView? = null

    /** 마지막으로 로그에 남긴 스캔 모드. 바뀔 때만 남기려고 들고 있다. */
    private var lastMode: String? = null

    override fun onBind(intent: Intent?): IBinder? = null

    override fun onCreate() {
        super.onCreate()
        startInForeground()
        show()
        startCore()
        listenToSwitch()
    }

    /**
     * 스위치를 듣는다.
     *
     * 눌림·뗌을 그대로 코어에 넘긴다. 짧게/길게 판정도, 그래서 무엇을 할지도 코어가
     * 정한다. 여기서 흉내 내면 데스크톱과 갈라진다.
     */
    private fun listenToSwitch() {
        usb =
            UsbSwitch(this) { event ->
                when (event) {
                    is UsbSwitch.Event.Connected ->
                        android.util.Log.i(TAG, "스위치 붙음 ${event.name}")

                    UsbSwitch.Event.Disconnected -> {
                        android.util.Log.w(TAG, "스위치 빠짐")
                        Core.switchLost()
                    }

                    UsbSwitch.Event.Press -> Core.pressed()

                    UsbSwitch.Event.Release -> Core.released()
                }
            }
        usb?.start()
    }

    /** 코어가 시키는 것을 실제로 한다. */
    private inner class Bridge : Core.Callbacks {
        override fun inject(action: Int): Boolean {
            val service = HanbeonAccessibilityService.instance
            if (service == null) {
                android.util.Log.w(TAG, "접근성 서비스가 꺼져 있습니다")
                return false
            }
            return when (action) {
                0 -> service.moveNext()
                1 -> service.movePrevious()
                2 -> service.select()
                // 설정 화면 열기는 키 주입이 아니라 우리 앱 내부 동작이다.
                3 -> true
                else -> false
            }
        }

        override fun undo(mapping: Int): Boolean =
            HanbeonAccessibilityService.instance?.back() ?: false

        override fun openSettings(unused: Int): Boolean {
            val intent =
                Intent(this@OverlayService, MainActivity::class.java)
                    .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            startActivity(intent)
            return true
        }

        override fun fitCells(extras: Int) {
            controller?.post { controller?.fitCells(extras) }
        }

        override fun cue(cue: Int) {
            // 소리는 아직 없다. 화면 강조만으로는 원칙 4(두 감각)를 못 지킨다.
        }

        override fun setSound(enabled: Boolean) = Unit

        override fun publishState(json: String) {
            logMode(json)
            controller?.post { controller?.render(json) }
        }

        override fun publishError(json: String) {
            android.util.Log.w(TAG, "오류 $json")
        }

        override fun publishInterval(json: String) {
            android.util.Log.i(TAG, "간격 $json")
            controller?.post { controller?.notice(json) }
        }

        override fun publishPreset(json: String) {
            android.util.Log.i(TAG, "앱별 칸 $json")
        }

        override fun saveProfile(json: String) {
            runCatching {
                java.io.File(filesDir, "profile.json").writeText(json)
            }
        }
    }

    /**
     * 스캔 모드가 바뀔 때만 남긴다.
     *
     * 커서 위치까지 남기면 주사 간격마다 한 줄씩 쌓여 로그가 못 쓰게 된다. 모드는
     * 사용자 입력에서만 바뀌므로 드물다. 정지인지 스캔 중인지를 화면만 보고
     * 구분하지 못해 실기에서 한참 헤맸다.
     */
    private fun logMode(json: String) {
        val mode = runCatching { org.json.JSONObject(json).optString("mode") }.getOrNull() ?: return
        if (mode == lastMode) return
        lastMode = mode
        android.util.Log.i(TAG, "모드 $mode")
    }

    /** 코어를 띄운다. 프로필이 없으면 코어가 기본값으로 시작한다. */
    private fun startCore() {
        val profile =
            runCatching { java.io.File(filesDir, "profile.json").readText() }
                .getOrDefault("{}")
        val logs = java.io.File(filesDir, "logs").apply { mkdirs() }
        val ok = Core.start(Bridge(), profile, logs.absolutePath)
        android.util.Log.i(TAG, "코어 ${if (ok) "시작됨" else "시작 실패"}")
    }

    private fun startInForeground() {
        val manager = getSystemService(NotificationManager::class.java)
        manager.createNotificationChannel(
            NotificationChannel(
                CHANNEL,
                "한번 실행 중",
                // 낮게 잡는다. 알림음이 울리면 스캔 소리와 섞여 사용자가 무엇이
                // 일어났는지 구분하지 못한다.
                NotificationManager.IMPORTANCE_LOW,
            ),
        )

        val notice =
            Notification.Builder(this, CHANNEL)
                .setContentTitle("한번이 실행 중입니다")
                .setContentText("스위치로 화면을 조작할 수 있습니다")
                .setSmallIcon(android.R.drawable.ic_menu_compass)
                .setOngoing(true)
                .build()

        startForeground(NOTIFICATION_ID, notice)
    }

    private fun show() {
        if (!Settings.canDrawOverlays(this)) {
            // 권한 없이 창을 올리면 예외로 죽는다. 조용히 물러나고 안내 화면이
            // 권한을 받게 둔다.
            stopSelf()
            return
        }

        val manager = getSystemService(WindowManager::class.java)
        // 창을 하나라도 올리기 전에 잡아 둔다. 컨트롤러를 올리다 실패해도
        // 먼저 올린 강조 창을 걷어낼 수 있어야 한다.
        windows = manager

        // 강조 테두리를 먼저 올린다. 나중에 올린 창이 위에 놓이므로, 순서가
        // 뒤집히면 대상 요소의 테두리가 컨트롤러를 가로질러 그려진다. 사용자가
        // 커서 위치를 읽는 화면이 가려지면 다음에 무엇이 올지 알 수 없다.
        showHighlight(manager)

        val view = ControllerView(this)

        // 폭을 못 박는다. WRAP_CONTENT로 두면 안쪽 칸의 가중치가 0폭으로 무너져
        // 컨트롤러가 화면 구석의 가는 띠가 되고, `Enter` 같은 글자는 줄바꿈된다.
        val width =
            android.util.TypedValue.applyDimension(
                android.util.TypedValue.COMPLEX_UNIT_DIP,
                CONTROLLER_WIDTH_DP,
                resources.displayMetrics,
            ).toInt()

        val params =
            WindowManager.LayoutParams(
                width,
                WindowManager.LayoutParams.WRAP_CONTENT,
                WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,
                // NOT_FOCUSABLE이 이 앱의 생명줄이다. 포커스를 받으면 우리가 옮기려는
                // 대상 앱의 포커스를 뺏어, 정작 조작할 것이 사라진다. 데스크톱에서
                // NSPanel과 WS_EX_NOACTIVATE로 애써 만드는 상태가 여기서는 기본이다.
                //
                // NOT_TOUCHABLE도 함께 건다. 컨트롤러는 **보여 주기만 한다** —
                // 조작은 스위치로 한다. 터치를 삼키면 두 가지가 깨진다. 선택할 때
                // 보내는 실제 두드림이 컨트롤러 뒤에 있는 요소 대신 우리에게
                // 먹히고, 보호자가 그 자리의 앱을 만질 수 없다.
                WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or
                    WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,
                PixelFormat.TRANSLUCENT,
            )
        params.gravity = Gravity.BOTTOM or Gravity.END
        params.x = MARGIN
        params.y = MARGIN

        manager.addView(view, params)
        controller = view

        // 컨트롤러가 어디를 덮고 있는지 알린다. 선택할 때 보내는 두드림이 이
        // 자리에 떨어지면 대상 앱이 아니라 우리에게 먹힌다.
        view.addOnLayoutChangeListener { _, _, _, _, _, _, _, _, _ ->
            val at = IntArray(2)
            view.getLocationOnScreen(at)
            val rect =
                android.graphics.Rect(at[0], at[1], at[0] + view.width, at[1] + view.height)
            if (rect != HanbeonAccessibilityService.controllerBounds) {
                HanbeonAccessibilityService.controllerBounds = rect
                android.util.Log.i(TAG, "컨트롤러 자리 $rect")
            }
        }
    }

    /**
     * 고르고 있는 요소에 테두리를 그릴 창.
     *
     * 화면 전체를 덮되 **터치를 통과시킨다**(`FLAG_NOT_TOUCHABLE`). 안 그러면 이
     * 창이 대상 앱의 터치를 모두 삼켜서, 보호자가 화면을 만질 수 없게 된다.
     */
    private fun showHighlight(manager: WindowManager) {
        val view = HighlightView(this)
        val params =
            WindowManager.LayoutParams(
                WindowManager.LayoutParams.MATCH_PARENT,
                WindowManager.LayoutParams.MATCH_PARENT,
                WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,
                WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or
                    WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE or
                    WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS or
                    WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,
                PixelFormat.TRANSLUCENT,
            )
        manager.addView(view, params)
        highlight = view

        HanbeonAccessibilityService.onFocusMoved = { bounds -> view.show(bounds) }
    }

    override fun onDestroy() {
        HanbeonAccessibilityService.onFocusMoved = null
        HanbeonAccessibilityService.controllerBounds = null
        highlight?.let { view -> runCatching { windows?.removeView(view) } }
        highlight = null
        usb?.stop()
        usb = null
        controller?.let { view -> runCatching { windows?.removeView(view) } }
        controller = null
        windows = null
        super.onDestroy()
    }

    companion object {
        private const val TAG = "한번"
        private const val CHANNEL = "hanbeon.overlay"
        private const val NOTIFICATION_ID = 1

        /** 화면 가장자리와의 여백. 붙어 있어도 칸 자리는 읽힌다. */
        private const val MARGIN = 12

        /// 스위치 사용자는 곁눈으로도 자리를 알아봐야 하지만, 컨트롤러가 크면
        /// 그만큼 조작할 앱을 가린다. 접근성 서비스는 가려 두드릴 수 없는 요소를
        /// 스캔 대상에서 빼 버리므로 폭은 기호가 읽히는 최소한만 쓴다.
        private const val CONTROLLER_WIDTH_DP = 200f

        fun start(context: android.content.Context) {
            val intent = Intent(context, OverlayService::class.java)
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                context.startForegroundService(intent)
            } else {
                context.startService(intent)
            }
        }

        fun stop(context: android.content.Context) {
            context.stopService(Intent(context, OverlayService::class.java))
        }
    }
}

package kr.devfive.hanbeon

import android.accessibilityservice.AccessibilityService
import android.util.Log
import android.view.View
import android.view.accessibility.AccessibilityEvent
import android.view.accessibility.AccessibilityNodeInfo
import android.view.accessibility.AccessibilityWindowInfo

/**
 * 대상 앱을 실제로 조작하는 쪽.
 *
 * 데스크톱은 `Tab`·`Enter`를 OS에 주입하지만 안드로이드는 다른 앱으로의 키 주입을
 * 막는다. 허용된 길은 접근성 서비스뿐이고, 여기서는 키를 보내는 대신 **접근성
 * 포커스를 노드 트리에서 옮긴다**(PRD 5.5).
 *
 * 스위치 입력은 여기로 오지 않는다. 아두이노가 HID 키보드가 아니라 시리얼로
 * `P`/`R`을 보내기 때문이다(PRD 7절). 이 서비스는 **출력 전용**이다.
 */
class HanbeonAccessibilityService : AccessibilityService() {
    /**
     * 마지막으로 우리가 옮긴 자리.
     *
     * 스캔 위치는 우리가 쥔다. 데스크톱에서 상태기계가 커서를 쥐는 것과 같은
     * 이유다 — 위치를 남에게 물으면 답이 흔들려 다음에 무엇이 올지 예측할 수 없다.
     */
    private var lastFocused: AccessibilityNodeInfo? = null

    /** 방금 화면을 굴렸는가. 굴린 뒤 한 번은 시스템에 자리를 되묻지 않는다. */
    private var resumeFromEdge = false

    /** 굴림이 끝난 뒤 좌표를 다시 읽으려고 쓴다. */
    private val main = android.os.Handler(android.os.Looper.getMainLooper())

    override fun onServiceConnected() {
        super.onServiceConnected()
        instance = this
        Log.i(TAG, "접근성 서비스 연결됨")
    }

    override fun onDestroy() {
        if (instance === this) instance = null
        super.onDestroy()
    }

    /**
     * 지금 앞에 있는 앱이 바뀌면 알린다.
     *
     * 데스크톱이 300ms마다 물어보던 것을 여기서는 시스템이 밀어 준다.
     * 앱별 칸(PRD F11)은 이 신호로만 갈아 끼운다.
     */
    override fun onAccessibilityEvent(event: AccessibilityEvent?) {
        if (event?.eventType == AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED) {
            val app = event.packageName?.toString() ?: return
            if (app != foreground) {
                foreground = app
                // 앱이 바뀌면 자리를 버린다. 이전 앱의 노드를 들고 있으면 새 화면에서
                // 엉뚱한 곳을 가리킨다.
                lastFocused = null
                Log.i(TAG, "앞에 있는 앱: $app")
            }
        }
    }

    override fun onInterrupt() = Unit

    /** 다음 요소로. 데스크톱의 `Tab`에 해당한다. */
    fun moveNext(): Boolean = move(View.FOCUS_FORWARD)

    /** 이전 요소로. 데스크톱의 `Shift+Tab`에 해당한다. */
    fun movePrevious(): Boolean = move(View.FOCUS_BACKWARD)

    /**
     * 지금 포커스를 가진 것을 고른다. 데스크톱의 `Enter`에 해당한다.
     *
     * 누를 수 없는 노드에 포커스가 있으면 누를 수 있는 조상을 찾아 올라간다.
     * 목록의 한 줄에서 실제로 클릭을 받는 것은 바깥 컨테이너인 경우가 흔하다.
     */
    fun select(): Boolean {
        val focused = lastFocused ?: focusedNode()
        if (focused == null) {
            Log.w(TAG, "선택 실패: 고른 요소가 없음")
            return false
        }

        // 우리 자신은 누르지 않는다. 컨트롤러의 칸을 눌러 버리면 사용자가
        // 고르려던 것 대신 우리 UI가 반응하고, 되돌릴 방법이 없다.
        if (isOurs(focused)) {
            Log.w(TAG, "선택 실패: 우리 앱의 요소라 누르지 않음")
            return false
        }

        // 사람이 하듯 그 자리를 실제로 두드린다.
        //
        // `ACTION_CLICK`을 먼저 썼다가 실기에서 크게 헤맸다. 웹 콘텐츠에서는
        // 그것이 **참을 돌려주고도 링크를 열지 않는다.** 로그에는 '선택 됨'이
        // 찍히는데 화면은 그대로여서, 되는 줄 알고 넘어가기 쉽다.
        if (tap(focused)) return true

        // 두드릴 수 없을 때만 semantic 액션으로 물러선다. 좌표가 없거나 화면
        // 밖에 있는 요소가 여기 온다.
        var node: AccessibilityNodeInfo? = focused
        var depth = 0
        while (node != null) {
            if (isOurs(node)) break
            if (node.isClickable && node.performAction(AccessibilityNodeInfo.ACTION_CLICK)) {
                Log.i(TAG, "선택 됨(액션) ${describe(node)} (조상 $depth 단계 위)")
                return true
            }
            node = node.parent
            depth += 1
        }

        Log.w(TAG, "선택 실패: 누를 수 없음 ${describe(focused)}")
        return false
    }

    /**
     * 요소의 한가운데를 실제로 두드린다.
     *
     * 화면 밖으로 걸친 요소는 보이는 부분의 한가운데를 잡는다. 요소의 기하학적
     * 중심이 화면 밖이면 두드려도 아무 데도 닿지 않는다.
     */
    private fun tap(node: AccessibilityNodeInfo): Boolean {
        val bounds = android.graphics.Rect()
        node.getBoundsInScreen(bounds)

        val screen =
            android.graphics.Rect(
                0,
                0,
                resources.displayMetrics.widthPixels,
                resources.displayMetrics.heightPixels,
            )
        if (!bounds.intersect(screen)) {
            Log.w(TAG, "두드리기 건너뜀: 화면 밖 ${describe(node)}")
            return false
        }

        val point = tapPoint(bounds) ?: run {
            Log.w(TAG, "두드리기 건너뜀: 컨트롤러에 완전히 가림 ${describe(node)}")
            return false
        }

        val path =
            android.graphics.Path().apply {
                moveTo(point.x, point.y)
            }
        val gesture =
            android.accessibilityservice.GestureDescription.Builder()
                .addStroke(
                    android.accessibilityservice.GestureDescription.StrokeDescription(
                        path,
                        0L,
                        TAP_MS,
                    ),
                )
                .build()

        val sent = dispatchGesture(gesture, null, null)
        Log.i(
            TAG,
            "두드림 ${if (sent) "보냄" else "실패"} " +
                "(${point.x.toInt()}, ${point.y.toInt()}) ${describe(node)}",
        )
        return sent
    }

    /**
     * 어디를 두드릴지 고른다. 가릴 것이 없으면 한가운데다.
     *
     * 컨트롤러는 터치를 받는 창이라, 그 위를 두드리면 대상 앱이 아니라 우리에게
     * 먹혀 아무 일도 일어나지 않는다. 터치를 통과시키면 될 것 같지만 그럴 수
     * 없다 — 안드로이드 12부터 통과시키는 오버레이는 **불투명도가 강제로
     * 낮춰져서**(탭재킹 방지) 컨트롤러가 비쳐 보인다. 저시력 사용자에게 대비는
     * 협상 대상이 아니다.
     *
     * 그래서 컨트롤러를 피해서 두드린다. 기사 한 줄처럼 가로로 긴 요소는 왼쪽이
     * 남고, 세로로 긴 것은 위쪽이 남는다. 둘 다 없으면 두드리지 않는다.
     */
    private fun tapPoint(bounds: android.graphics.Rect): android.graphics.PointF? {
        val panel = controllerBounds
        if (panel == null || !android.graphics.Rect.intersects(bounds, panel)) {
            return android.graphics.PointF(bounds.exactCenterX(), bounds.exactCenterY())
        }

        val leftWidth = panel.left - bounds.left
        if (leftWidth >= MIN_TAP_PX) {
            return android.graphics.PointF(
                bounds.left + leftWidth / 2f,
                bounds.exactCenterY(),
            )
        }

        val aboveHeight = panel.top - bounds.top
        if (aboveHeight >= MIN_TAP_PX) {
            return android.graphics.PointF(
                bounds.exactCenterX(),
                bounds.top + aboveHeight / 2f,
            )
        }

        return null
    }

    private fun describe(node: AccessibilityNodeInfo): String {
        val bounds = android.graphics.Rect()
        node.getBoundsInScreen(bounds)
        return "${node.className} \"${node.text ?: node.contentDescription ?: ""}\" " +
            "y=${bounds.top} clickable=${node.isClickable}"
    }

    /** 되돌리기. 데스크톱의 뒤로가기 단축키에 해당한다(PRD F6). */
    fun back(): Boolean = performGlobalAction(GLOBAL_ACTION_BACK)

    /**
     * 포커스를 한 칸 옮긴다.
     *
     * `focusSearch`를 쓰지 않는다. 그것은 **입력 포커스**를 위한 탐색이라, 돌려준
     * 노드가 접근성 포커스를 거부하는 일이 잦다. 실제로 크롬에서 EditText를
     * 돌려주고는 `ACTION_ACCESSIBILITY_FOCUS`가 거부됐다.
     *
     * 대신 트리를 훑어 순서를 직접 만든다. 순서를 우리가 쥐고 있어야 `<`로
     * 되돌아가는 것이 `>`의 정확한 역이 된다. 그게 이 제품의 핵심 약속이다.
     */
    private fun move(direction: Int): Boolean {
        val root = targetRoot()
        if (root == null) {
            Log.w(TAG, "이동 실패: 조작할 앱의 창을 못 찾음")
            return false
        }

        val order = focusables(root)
        if (order.isEmpty()) {
            // 지금 보이는 곳에 고를 것이 하나도 없을 수 있다. 컨트롤러가 화면
            // 아래쪽을 덮고 있어서 그 위쪽이 그림뿐인 화면이 그렇다. 굴려서
            // 다음 내용을 드러낸다 — 여기서 물러서면 사용자는 갇힌다.
            if (scrollPage(root, direction == View.FOCUS_FORWARD)) {
                Log.i(TAG, "고를 것이 없어 화면을 굴림")
                lastFocused = null
                resumeFromEdge = true
                return true
            }
            Log.w(TAG, "이동 실패: 초점 가능한 요소가 없음 (root=${root.packageName})")
            return false
        }

        // 시스템에 물으면 안 된다. 웹뷰 안에 포커스가 있으면 컨테이너인 웹뷰를
        // 돌려줘서, 매번 같은 자리로 읽히고 커서가 제자리를 맴돈다. 우리가 마지막에
        // 옮긴 곳을 기억해 두고 그것을 새 목록에서 찾는다.
        val remembered = lastFocused
        var at = if (remembered == null) -1 else order.indexOfFirst { it == remembered }
        if (at < 0 && !resumeFromEdge) {
            val system = root.findFocus(AccessibilityNodeInfo.FOCUS_ACCESSIBILITY)
            at = order.indexOfFirst { it == system }
        }
        // 굴린 직후에는 시스템에 되묻지 않는다. 크롬이 아직 굴리기 전에 고른 것을
        // 쥐고 있어서, 물으면 방금 놓은 자리로 그대로 돌아와 또 굴리기만 한다.
        resumeFromEdge = false
        val forward = direction == View.FOCUS_FORWARD

        // 포커스를 거부하는 노드가 있다. 거기서 멈추면 `lastFocused`가 그대로라
        // 다음 눌림에도 같은 노드를 또 시도하게 되고, 커서가 영영 움직이지 않는다.
        // 실기에서 크롬의 빈 FrameLayout 하나가 계속 거부해 `>`가 아무 일도 하지
        // 않았고, 고른 것이 없으니 `Enter`도 먹힐 수 없었다.
        //
        // 그래서 받아 주는 것을 만날 때까지 같은 방향으로 계속 나아간다. 방향을
        // 지키는 것이 중요하다 — `<`가 `>`의 정확한 역이어야 지나쳐도 되돌아올 수
        // 있다.
        //
        // 되감기 전에 먼저 끝까지 가 본다. 목록 끝에 닿았다는 것을 자리 번호로
        // 판정하면 안 된다. 마지막 몇 개가 포커스를 거부하면 커서가 마지막 자리에
        // 아예 도달하지 못해, 끝에 닿았다는 판정이 영영 참이 되지 않는다.
        val tail = if (forward) (at + 1) until order.size else (at - 1) downTo 0
        for (i in tail) {
            if (focusOn(order[i], at, i, order.size)) return true
        }

        // 여기까지 왔다는 것은 이 방향으로 더 갈 데가 없다는 뜻이다. 순서에는
        // **지금 보이는 것만** 들어 있어서, 굴리지 않으면 화면 밖 내용에 영영
        // 닿을 수 없다. 되감기는 굴릴 데가 없을 때만 한다.
        if (at >= 0 && scrollPage(root, forward)) {
            Log.i(TAG, "화면을 굴림 (${if (forward) "아래" else "위"}) at=$at/${order.size}")
            // 자리를 놓는다. 굴려도 크롬은 지금 고른 것을 화면 안에 붙들어 두므로,
            // 자리를 쥐고 있으면 다음 눌림에도 여전히 끝이라 또 굴리기만 하고
            // 영영 나아가지 못한다.
            //
            // 놓으면 다음 눌림은 새 화면의 처음부터(`>`) 또는 끝부터(`<`) 이어간다.
            // 방향에 맞는 쪽에서 시작하므로 `<`는 여전히 `>`의 역이다.
            lastFocused = null
            resumeFromEdge = true
            // 굴린 직후에는 노드 트리가 아직 안 바뀌어 있다. 여기서 기다리면
            // 스위치 처리가 그만큼 늦어져 눌림 판정이 흔들린다. 다음 눌림에서
            // 새 목록을 만나 이어서 옮긴다.
            return true
        }

        val head = if (forward) 0..at else (order.size - 1) downTo (at + 1)
        for (i in head) {
            if (focusOn(order[i], at, i, order.size)) return true
        }

        Log.w(TAG, "이동 실패: ${order.size}개가 모두 포커스를 거부함")
        return false
    }

    /** 이 노드로 커서를 옮긴다. 거부하면 거짓. */
    private fun focusOn(
        target: AccessibilityNodeInfo,
        from: Int,
        to: Int,
        total: Int,
    ): Boolean {
        if (!target.performAction(AccessibilityNodeInfo.ACTION_ACCESSIBILITY_FOCUS)) return false

        lastFocused = target

        // 화면 가장자리에 걸친 요소만 안으로 끌어들인다. 반쯤 잘려 보이는 것을
        // 고르라고 하면 사용자는 무엇을 고르는지 확인할 수 없다.
        //
        // **이미 다 보이는 것에는 걸지 않는다.** 웹페이지 전체를 담는 웹뷰가
        // 순서에 끼는데, 거기에 걸면 문서 첫머리가 끌어올려져 애써 굴린 화면이
        // 통째로 맨 위로 되돌아간다. 실기에서 이것 때문에 화면 아래쪽으로
        // 나아가지 못하고 같은 자리를 맴돌았다.
        val bounds = android.graphics.Rect()
        target.getBoundsInScreen(bounds)
        val screen =
            android.graphics.Rect(
                0,
                0,
                resources.displayMetrics.widthPixels,
                resources.displayMetrics.heightPixels,
            )
        if (!screen.contains(bounds)) {
            target.performAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SHOW_ON_SCREEN.id)
        }

        publishBounds(target)
        Log.i(TAG, "이동 됨 $from->$to/$total ${describe(target)}")
        return true
    }

    /**
     * 훑어서 순서를 만든다.
     *
     * 화면에 보이고, 켜져 있고, 누르거나 초점을 받을 수 있는 것만 넣는다. 보이지
     * 않는 것을 순서에 넣으면 사용자는 아무 일도 일어나지 않는 칸을 만나고,
     * 그 순간 자리로 동작을 기억하는 전제가 깨진다.
     */
    /**
     * 조작할 창의 노드 트리.
     *
     * `rootInActiveWindow`를 그대로 쓰면 안 된다. 설정 화면을 열거나 컨트롤러를
     * 만지면 활성 창이 **우리 자신**이 되고, 그러면 우리 앱을 스캔하려다 초점
     * 가능한 요소가 하나도 없어 이동이 통째로 실패한다. 실기에서 이 상태가
     * 이어지자 놓침이 쌓여 주사 간격이 1.8초에서 3.5초까지 늘어났다 —
     * 사용자는 실수한 적이 없는데 앱이 느려진다.
     *
     * 데스크톱의 가림 판정에도 '활성 앱이 우리 자신이면 건너뛴다'는 같은 규칙이
     * 있다. 우리가 앞에 있으면 뒤에 있는 대상 앱 창 중 가장 위의 것을 고른다.
     */
    private fun targetRoot(): AccessibilityNodeInfo? {
        val active = rootInActiveWindow
        if (active != null && !isOurs(active)) return active

        return windows
            .asSequence()
            .filter { it.type == AccessibilityWindowInfo.TYPE_APPLICATION }
            // 겹쳐 있으면 위에 있는 것이 사용자가 보고 있는 창이다.
            .sortedByDescending { it.layer }
            .mapNotNull { it.root }
            .firstOrNull { !isOurs(it) }
    }

    /**
     * 우리 앱의 노드인가.
     *
     * `packageName`은 `String`이 아니라 `CharSequence`다. `SpannedString` 같은
     * 다른 구현체가 오면 `==` 비교가 조용히 거짓이 되어 걸러지지 않는다.
     */
    private fun isOurs(node: AccessibilityNodeInfo): Boolean =
        node.packageName?.toString() == packageName

    /**
     * 굴릴 수 있는 조상을 찾아 한 화면 굴린다.
     *
     * 지금 고른 것에서 위로 올라가며 찾는다. 화면에 굴릴 수 있는 것이 여럿일 때
     * (목록 안의 목록) 사용자가 보고 있는 쪽을 굴려야 하기 때문이다.
     */
    private fun scrollPage(
        root: AccessibilityNodeInfo,
        forward: Boolean,
    ): Boolean {
        val action =
            if (forward) {
                AccessibilityNodeInfo.ACTION_SCROLL_FORWARD
            } else {
                AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD
            }

        var node: AccessibilityNodeInfo? = lastFocused
        while (node != null) {
            if (node.isScrollable && node.performAction(action)) return true
            node = node.parent
        }

        // 조상 사슬로 못 찾는 경우가 있다. 크롬의 웹 콘텐츠는 굴릴 수 있는 것이
        // 웹뷰인데, 가상 노드의 parent 를 따라가도 거기까지 닿지 않는다.
        // 트리에서 직접 찾는다.
        return scrollables(root).any { it.performAction(action) }
    }

    /** 굴릴 수 있는 것을 트리에서 모은다. 큰 것부터 — 바깥쪽이 화면을 굴린다. */
    private fun scrollables(root: AccessibilityNodeInfo): List<AccessibilityNodeInfo> {
        val out = mutableListOf<AccessibilityNodeInfo>()

        fun walk(node: AccessibilityNodeInfo?) {
            if (node == null || isOurs(node)) return
            if (node.isScrollable) out.add(node)
            for (i in 0 until node.childCount) walk(node.getChild(i))
        }

        walk(root)
        return out
    }

    /**
     * 강조 테두리를 그릴 곳을 알린다.
     *
     * 두 번 보낸다. `ACTION_SHOW_ON_SCREEN`이 화면을 굴리면 좌표가 바뀌는데,
     * 굴림이 끝나기 전에 읽은 값으로 그리면 테두리가 엉뚱한 곳에 남는다.
     * 잠시 뒤 노드를 다시 읽어 한 번 더 보낸다.
     */
    private fun publishBounds(node: AccessibilityNodeInfo) {
        val bounds = android.graphics.Rect()
        node.getBoundsInScreen(bounds)
        onFocusMoved?.invoke(bounds)

        main.postDelayed({
            if (node.refresh()) {
                val moved = android.graphics.Rect()
                node.getBoundsInScreen(moved)
                if (moved != bounds && !moved.isEmpty) onFocusMoved?.invoke(moved)
            }
        }, SCROLL_SETTLE_MS)
    }

    private fun focusables(root: AccessibilityNodeInfo): List<AccessibilityNodeInfo> {
        val out = mutableListOf<AccessibilityNodeInfo>()
        val screen =
            android.graphics.Rect(
                0,
                0,
                resources.displayMetrics.widthPixels,
                resources.displayMetrics.heightPixels,
            )
        val bounds = android.graphics.Rect()

        fun walk(node: AccessibilityNodeInfo?) {
            if (node == null) return
            // 우리 컨트롤러는 순서에 넣지 않는다. 스캔 대상은 대상 앱이지 우리가 아니다.
            if (isOurs(node)) return

            // 컨트롤러에 가려 두드릴 수 없는 것도 넣지 않는다. 커서가 거기 멈추면
            // 눌러도 아무 일이 없고, 그 순간 자리로 동작을 기억하는 전제가 깨진다.
            // 가려진 내용은 목록 끝에서 화면을 굴리면 위로 올라와 닿을 수 있다.
            node.getBoundsInScreen(bounds)
            val choosable = bounds.intersect(screen) && tapPoint(bounds) != null

            // 굴릴 수 있는 것은 고를 대상이 아니라 **내용을 담는 창**이다. 크롬의
            // 웹뷰가 여기 걸리는데, 거기에 접근성 포커스를 주는 것만으로 크롬이
            // 문서 첫머리로 굴러가 애써 내려온 화면이 통째로 맨 위로 돌아간다.
            // 실기에서 이것 때문에 화면 아래쪽으로 나아가지 못하고 맴돌았다.
            val usable =
                choosable &&
                    !node.isScrollable &&
                    node.isVisibleToUser &&
                    node.isEnabled &&
                    (node.isClickable || node.isFocusable || node.isEditable)
            if (usable) out.add(node)

            for (i in 0 until node.childCount) walk(node.getChild(i))
        }

        walk(root)
        return out
    }

    private fun focusedNode(): AccessibilityNodeInfo? {
        val root = targetRoot() ?: return null
        return root.findFocus(AccessibilityNodeInfo.FOCUS_ACCESSIBILITY)
            ?: root.findFocus(AccessibilityNodeInfo.FOCUS_INPUT)
    }

    companion object {
        private const val TAG = "한번"

        /** 굴림이 멎기를 기다리는 시간. 좌표를 다시 읽는 데만 쓴다. */
        private const val SCROLL_SETTLE_MS = 350L

        /** 두드리는 시간. 길게 누름으로 읽히지 않을 만큼 짧게 잡는다. */
        private const val TAP_MS = 60L

        /** 컨트롤러를 피해 두드릴 때 필요한 최소 여백. 이보다 좁으면 빗나간다. */
        private const val MIN_TAP_PX = 48

        /** 컨트롤러가 화면에서 차지하는 자리. 두드릴 때 피해야 한다. */
        @Volatile
        var controllerBounds: android.graphics.Rect? = null

        /** 켜져 있으면 그 인스턴스. 꺼져 있으면 `null`. */
        @Volatile
        var instance: HanbeonAccessibilityService? = null
            private set

        /** 지금 앞에 있는 앱의 패키지 이름. 앱별 칸을 고르는 근거다(PRD F11). */
        @Volatile
        var foreground: String? = null
            private set

        /** 포커스가 옮겨 갈 때마다 그 화면 좌표를 받는다. 테두리를 그리는 쪽이 쓴다. */
        @Volatile
        var onFocusMoved: ((android.graphics.Rect) -> Unit)? = null
    }
}

package kr.devfive.hanbeon

import android.app.PendingIntent
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.hardware.usb.UsbConstants
import android.hardware.usb.UsbDevice
import android.hardware.usb.UsbDeviceConnection
import android.hardware.usb.UsbEndpoint
import android.hardware.usb.UsbInterface
import android.hardware.usb.UsbManager
import android.util.Log
import kotlin.concurrent.thread

/**
 * 아두이노 스위치를 USB 시리얼로 읽는다.
 *
 * 스위치는 HID 키보드가 아니다. 아두이노 우노(ATmega328P)는 USB HID가 물리적으로
 * 불가능해서 펌웨어가 눌림에 `P` 뗌에 `R`을 보낸다(PRD 7절). 그래서 접근성 서비스의
 * `onKeyEvent()`로는 영영 오지 않고, USB Host API로 직접 읽어야 한다.
 *
 * 데스크톱의 `switch.rs`와 같은 프로토콜을 쓴다. 프로토콜을 바꾸면 양쪽을 함께 고친다.
 *
 * CDC-ACM을 직접 다룬다. 라이브러리를 들이지 않는 이유는 우리 보드가 정품 우노라
 * 표준 CDC-ACM이기 때문이다. 클론(CH340)을 받게 되면 그때 라이브러리를 검토한다.
 */
class UsbSwitch(
    private val context: Context,
    private val onEvent: (Event) -> Unit,
) {
    sealed interface Event {
        data class Connected(val name: String) : Event

        data object Disconnected : Event

        /** 눌림. */
        data object Press : Event

        /** 뗌. */
        data object Release : Event
    }

    private var connection: UsbDeviceConnection? = null
    private var reader: Thread? = null
    @Volatile private var running = false

    private val permissionReceiver =
        object : BroadcastReceiver() {
            override fun onReceive(
                context: Context,
                intent: Intent,
            ) {
                if (intent.action != ACTION_PERMISSION) return
                val granted = intent.getBooleanExtra(UsbManager.EXTRA_PERMISSION_GRANTED, false)
                if (granted) {
                    open()
                } else {
                    // 스위치만 쓰는 사용자는 이 대화상자를 조작할 수 없다.
                    // 보호자가 눌러 줘야 한다(PRD 5.4와 같은 전제).
                    Log.w(TAG, "USB 권한이 거부됐습니다. 보호자가 허용해 줘야 합니다.")
                }
            }
        }

    fun start() {
        context.registerReceiver(
            permissionReceiver,
            IntentFilter(ACTION_PERMISSION),
            Context.RECEIVER_NOT_EXPORTED,
        )
        open()
    }

    fun stop() {
        running = false
        reader?.interrupt()
        reader = null
        connection?.close()
        connection = null
        runCatching { context.unregisterReceiver(permissionReceiver) }
    }

    private fun manager() = context.getSystemService(UsbManager::class.java)

    private fun findBoard(): UsbDevice? =
        manager().deviceList.values.firstOrNull { device ->
            device.vendorId == ARDUINO_VENDOR || hasCdc(device)
        }

    private fun hasCdc(device: UsbDevice): Boolean =
        (0 until device.interfaceCount).any { i ->
            device.getInterface(i).interfaceClass == UsbConstants.USB_CLASS_CDC_DATA
        }

    private fun open() {
        val device = findBoard()
        if (device == null) {
            Log.w(TAG, "스위치를 찾지 못했습니다. 꽂혀 있는지 확인해 주세요.")
            return
        }

        if (!manager().hasPermission(device)) {
            val intent =
                PendingIntent.getBroadcast(
                    context,
                    0,
                    Intent(ACTION_PERMISSION).setPackage(context.packageName),
                    PendingIntent.FLAG_IMMUTABLE,
                )
            manager().requestPermission(device, intent)
            return
        }

        Log.i(
            TAG,
            "보드 인터페이스 ${device.interfaceCount}개: " +
                (0 until device.interfaceCount).joinToString {
                    "#${device.getInterface(it).id}/cls=${device.getInterface(it).interfaceClass}"
                },
        )

        val data = dataInterface(device)
        if (data == null) {
            Log.w(TAG, "CDC 데이터 인터페이스를 찾지 못했습니다.")
            return
        }

        val opened = manager().openDevice(device) ?: return
        if (!opened.claimInterface(data, true)) {
            Log.w(TAG, "인터페이스를 잡지 못했습니다.")
            opened.close()
            return
        }

        configure(opened, device)

        val input = endpoint(data, UsbConstants.USB_DIR_IN)
        val output = endpoint(data, UsbConstants.USB_DIR_OUT)
        if (input == null) {
            Log.w(TAG, "읽기 엔드포인트가 없습니다.")
            opened.close()
            return
        }

        connection = opened
        onEvent(Event.Connected(device.deviceName))
        Log.i(TAG, "스위치 연결됨 ${device.deviceName} (VID ${device.vendorId})")

        // 우리 보드가 맞는지 물어본다. 데스크톱과 같은 핸드셰이크다.
        output?.let { opened.bulkTransfer(it, HELLO, HELLO.size, 500) }

        running = true
        reader = thread(name = "hanbeon-usb") { readLoop(opened, input) }
    }

    /**
     * 보드레이트와 DTR을 맞춘다.
     *
     * 이걸 빠뜨리면 포트는 열리는데 한 바이트도 오지 않는다. 아두이노는 DTR이
     * 올라가야 말을 시작한다.
     */
    private fun configure(
        connection: UsbDeviceConnection,
        device: UsbDevice,
    ) {
        val control = device.getInterface(0)
        connection.claimInterface(control, true)

        // SET_LINE_CODING: 115200 8N1
        val coding =
            byteArrayOf(
                0x00, 0xC2.toByte(), 0x01, 0x00, // 115200 리틀엔디언
                0x00, // 정지 비트 1
                0x00, // 패리티 없음
                0x08, // 데이터 8비트
            )
        val codingResult = connection.controlTransfer(0x21, 0x20, 0, 0, coding, coding.size, 500)

        // SET_CONTROL_LINE_STATE: DTR|RTS
        val lineResult = connection.controlTransfer(0x21, 0x22, 0x03, 0, null, 0, 500)
        Log.i(TAG, "보드레이트 설정=$codingResult DTR설정=$lineResult (음수면 실패)")
    }

    private fun dataInterface(device: UsbDevice): UsbInterface? =
        (0 until device.interfaceCount)
            .map { device.getInterface(it) }
            .firstOrNull { it.interfaceClass == UsbConstants.USB_CLASS_CDC_DATA }

    private fun endpoint(
        target: UsbInterface,
        direction: Int,
    ): UsbEndpoint? =
        (0 until target.endpointCount)
            .map { target.getEndpoint(it) }
            .firstOrNull {
                it.direction == direction && it.type == UsbConstants.USB_ENDPOINT_XFER_BULK
            }

    private fun readLoop(
        connection: UsbDeviceConnection,
        input: UsbEndpoint,
    ) {
        val buffer = ByteArray(256)
        // 시리얼은 줄 단위로 오지 않는다. 조각을 모아 완성된 줄만 꺼낸다.
        val pending = StringBuilder()
        var idle = 0
        Log.i(TAG, "읽기 시작 (엔드포인트 ${input.address}, 최대 ${input.maxPacketSize}바이트)")

        while (running) {
            val read = connection.bulkTransfer(input, buffer, buffer.size, 200)
            if (read <= 0) {
                // 아무것도 안 올 때 조용히 도는 것과 통로가 막힌 것을 구분해야 한다.
                if (++idle % 50 == 0) Log.d(TAG, "읽기 대기 중 (마지막 결과 $read)")
                continue
            }
            idle = 0
            Log.d(TAG, "받음 ${read}바이트: ${String(buffer, 0, read, Charsets.US_ASCII).trim()}")

            pending.append(String(buffer, 0, read, Charsets.US_ASCII))
            while (true) {
                val at = pending.indexOf("\n")
                if (at < 0) break
                val line = pending.substring(0, at).trim()
                pending.delete(0, at + 1)
                dispatch(line)
            }
        }

        onEvent(Event.Disconnected)
    }

    private fun dispatch(line: String) {
        when (line) {
            "P" -> onEvent(Event.Press)
            "R" -> onEvent(Event.Release)
            IDENT -> Log.i(TAG, "우리 보드가 맞습니다")
            // 아두이노는 리셋 직후 잡음을 뱉는다. 모르는 줄에 반응해 눌린 것으로
            // 치면 사용자는 누르지도 않은 동작을 겪는다.
            else -> if (line.isNotEmpty()) Log.d(TAG, "모르는 줄: $line")
        }
    }

    private companion object {
        const val TAG = "한번"
        const val ACTION_PERMISSION = "kr.devfive.hanbeon.USB_PERMISSION"
        const val ARDUINO_VENDOR = 0x2341
        const val IDENT = "HANBEON_UNO_V1"
        val HELLO = "HELLO\n".toByteArray(Charsets.US_ASCII)
    }
}

package kr.devfive.hanbeon

import android.app.Activity
import android.content.Intent
import android.graphics.Color
import android.net.Uri
import android.os.Bundle
import android.provider.Settings
import android.util.TypedValue
import android.view.Gravity
import android.view.ViewGroup
import android.widget.Button
import android.widget.LinearLayout
import android.widget.TextView

/**
 * 보호자가 쓰는 화면.
 *
 * 스위치만 쓰는 사용자는 이 화면을 조작할 수 없다. 권한 대화상자는 4칸으로 빠져나올
 * 수 없기 때문이다(PRD 5.4의 '보호자가 띄워 준다'와 같은 전제). 그래서 큼직하고
 * 단계가 짧아야 한다.
 */
class MainActivity : Activity() {
    private lateinit var status: TextView

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        val root =
            LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(24), dp(48), dp(24), dp(24))
                setBackgroundColor(Color.WHITE)
            }

        root.addView(
            TextView(this).apply {
                text = "한번"
                setTextSize(TypedValue.COMPLEX_UNIT_SP, 34f)
                setTextColor(Color.parseColor("#1B2124"))
            },
        )
        root.addView(
            TextView(this).apply {
                text = "스위치로 다른 앱을 조작하려면 아래 권한이 필요합니다."
                setTextSize(TypedValue.COMPLEX_UNIT_SP, 16f)
                setTextColor(Color.parseColor("#5A6468"))
                setPadding(0, dp(8), 0, dp(28))
            },
        )

        status =
            TextView(this).apply {
                setTextSize(TypedValue.COMPLEX_UNIT_SP, 16f)
                setPadding(0, dp(20), 0, 0)
            }

        root.addView(
            big("다른 앱 위에 표시 권한 열기") {
                startActivity(
                    Intent(
                        Settings.ACTION_MANAGE_OVERLAY_PERMISSION,
                        Uri.parse("package:$packageName"),
                    ),
                )
            },
        )
        root.addView(big("컨트롤러 켜기") { OverlayService.start(this) })
        root.addView(big("컨트롤러 끄기") { OverlayService.stop(this) })
        root.addView(status)

        setContentView(root)

        // 인텐트로도 켤 수 있게 둔다. 서비스 자체는 exported=false로 잠가 두어야
        // 아무 앱이나 우리 컨트롤러를 띄울 수 없는데, 그러면 adb로 검증할 길이
        // 없어진다. 이 통로는 우리 Activity를 거치므로 잠금이 풀리지 않는다.
        if (intent?.getBooleanExtra(EXTRA_START_OVERLAY, false) == true) {
            OverlayService.start(this)
        }
    }

    override fun onResume() {
        super.onResume()
        val allowed = Settings.canDrawOverlays(this)
        status.text =
            if (allowed) {
                "권한 있음. 컨트롤러를 켤 수 있습니다."
            } else {
                "권한 없음. 먼저 위 버튼으로 허용해 주세요."
            }
        status.setTextColor(
            if (allowed) Color.parseColor("#0E7A63") else Color.parseColor("#B3261E"),
        )
    }

    private fun big(
        label: String,
        onTap: () -> Unit,
    ): Button =
        Button(this).apply {
            text = label
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 18f)
            gravity = Gravity.CENTER
            setOnClickListener { onTap() }
            layoutParams =
                LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(64)).also {
                    it.bottomMargin = dp(12)
                }
        }

    companion object {
        const val EXTRA_START_OVERLAY = "start_overlay"
    }

    private fun dp(value: Int): Int =
        TypedValue.applyDimension(
            TypedValue.COMPLEX_UNIT_DIP,
            value.toFloat(),
            resources.displayMetrics,
        ).toInt()
}

