    ): TextView {
        val view =
            TextView(context).apply {
                text = GLYPHS[label] ?: label
                gravity = Gravity.CENTER
                setTextSize(TypedValue.COMPLEX_UNIT_SP, textSizeSp)
                // 줄 위아래의 빈 여백을 없애야 좁은 칸에 두 줄이 온전히 든다.
